# ============================================================
# Optogenetic Stimulation — Example Traces and PETH Summary
# ============================================================
#
# Description:
#   Generate representative dStr and vStr photometry traces and summarize optogenetic stimulation PETHs across mice.
#
#   - Preserve the original example recordings and time windows
#   - Identify stimulation episodes using the original algorithm
#   - Filter photometry traces using a Butterworth filter
#   - Import PETH files generated by script 01
#   - Plot mouse-specific mean responses and SEM
#   - Combine example traces and PETH panels
#
# Input:
#   oft_fp_opto_details.csv
#   <experiment>/videos/<video>.csv
#   <experiment>/signal/<video>_signal_df.csv
#   results/<video>/<video>_PETH.csv
#
# Output:
#   results/opto+dLight.pdf
#
# Author: Alessandro Contestabile
# ============================================================

# ============================================================
# 1. SETUP
# ============================================================
rm(list = ls())

suppressPackageStartupMessages({
  library(ggplot2)
  library(dplyr)
  library(cowplot)
  library(signal)
})

# ============================================================
# 2. PATHS AND PARAMETERS
# ============================================================

DATA_DIR <- "path/to/oft/opto+dLight"
OUT_DIR <- file.path(DATA_DIR, "results")
DETAILS_FILE <- file.path(DATA_DIR, "oft_fp_opto_details.csv")

FRAME_BEHAVIOR <- 1 / 30
PETH_WINDOW <- 2
BURST_INTERVAL <- 4

FILTER_ORDER <- 3
FILTER_CUTOFF <- 0.1

STIM_COLOR <- "steelblue"
STIM_DURATION <- 1

PETH_BIN_WIDTH <- 0.05

EXAMPLE_DSTR_INDEX <- 1
EXAMPLE_VSTR_INDEX <- 17

DSTR_XLIM <- c(374.4, 449.4)
VSTR_XLIM <- c(475.4667, 550.4667)

DSTR_YLIM <- c(-5, 15)
VSTR_YLIM <- c(-5, 12)

MY_COLORS <- c("#810F7C", "#8856A7", "#9EBCDA", "#8C96C6", "#BFD3E6")

dir.create(OUT_DIR, recursive = TRUE, showWarnings = FALSE)

# ============================================================
# 3. LOAD METADATA AND IDENTIFY RECORDINGS
# ============================================================

details <- read.csv(DETAILS_FILE, stringsAsFactors = FALSE)

required_cols <- c("mouse.ID", "group", "video", "experiment", "start.fp", "protocol", "intenisty")
stopifnot(all(required_cols %in% names(details)))

# Preserve the original recursive MAT-file ordering.
files_to_read <- list.files(DATA_DIR, pattern = "\\.mat$", recursive = TRUE)

if (length(files_to_read) < max(EXAMPLE_DSTR_INDEX, EXAMPLE_VSTR_INDEX)) {
  stop("Not enough MAT files to identify the original example recordings.")
}

# ============================================================
# 4. HELPER FUNCTIONS
# ============================================================

# ------------------------------------------------------------
# 4.1 Load and filter a representative recording
# ------------------------------------------------------------

load_example <- function(file_index) {
  
  mat_file <- files_to_read[file_index]
  
  # Original filename-based identification
  experiment <- substr(mat_file, 1, 7)
  video <- substr(mat_file, 16, nchar(mat_file) - 4)
  
  info <- details[details$video == video, , drop = FALSE]
  
  if (nrow(info) != 1) {
    stop("Expected exactly one metadata row for video: ", video)
  }
  
  bonsai_file <- file.path(DATA_DIR, experiment, "videos", paste0(video, ".csv"))
  signal_file <- file.path(DATA_DIR, experiment, "signal", paste0(video, "_signal_df.csv"))
  
  bonsai <- read.csv(bonsai_file)
  dF <- read.csv(signal_file)
  
  colnames(bonsai) <- c("timestamp", "time", "in")
  colnames(dF) <- c("time", "dF")
  
  bonsai$time <- bonsai$time * FRAME_BEHAVIOR
  bonsai <- bonsai[bonsai$time > as.numeric(info$start.fp) * FRAME_BEHAVIOR + 60, ]
  
  butter_filter <- butter(FILTER_ORDER, FILTER_CUTOFF)
  dF$dF <- as.numeric(signal::filter(butter_filter, dF$dF))
  
  # ----------------------------------------------------------
  # Original stimulation-onset detection
  # ----------------------------------------------------------
  
  episodes <- data.frame(
    episode.time = numeric(0),
    episode.number = numeric(0),
    episode.burst = numeric(0)
  )
  
  for (i in 2:(nrow(bonsai) - 1)) {
    
    if (bonsai[i, 2] > bonsai[1, 2] + PETH_WINDOW &&
        bonsai[i, 2] < bonsai[nrow(bonsai), 2] - PETH_WINDOW &&
        sum(bonsai[(i - round(PETH_WINDOW / FRAME_BEHAVIOR)):(i - 1), 3] == "True") == 0 &&
        bonsai[i, 3] == "True") {
      
      episodes[nrow(episodes) + 1, 1] <- bonsai[i, 2]
    }
  }
  
  if (nrow(episodes) == 0) {
    stop("No stimulation episodes detected for video: ", video)
  }
  
  # ----------------------------------------------------------
  # Original burst classification
  # ----------------------------------------------------------
  
  episodes[1, 2] <- 1
  episodes[1, 3] <- 1
  
  if (nrow(episodes) > 1) {
    
    for (i in 2:nrow(episodes)) {
      
      if (round(episodes[i, 1]) == round(episodes[i - 1, 1] + BURST_INTERVAL)) {
        episodes[i, 2] <- as.numeric(episodes[i - 1, 2]) + 1
        episodes[i, 3] <- as.numeric(episodes[i - 1, 3])
      }
      
      if (round(episodes[i, 1]) > round(episodes[i - 1, 1] + BURST_INTERVAL)) {
        episodes[i, 2] <- 1
        episodes[i, 3] <- as.numeric(episodes[i - 1, 3]) + 1
      }
    }
  }
  
  episodes$episode.end <- episodes$episode.time + STIM_DURATION
  
  list(dF = dF, episodes = episodes, info = info, video = video)
}


# ------------------------------------------------------------
# 4.2 Plot representative traces
# ------------------------------------------------------------

plot_example <- function(example, title, xlim_values, ylim_values, line_color) {
  
  ggplot(example$dF, aes(x = time, y = dF)) +
    geom_rect(
      data = example$episodes,
      aes(xmin = episode.time, xmax = episode.end,
          ymin = -Inf, ymax = Inf),
      inherit.aes = FALSE,
      fill = STIM_COLOR, alpha = 0.1
    ) +
    geom_line(color = line_color, linewidth = 0.45) +
    coord_cartesian(xlim = xlim_values, ylim = ylim_values) +
    labs(title = title, x = "Time (s)", y = "dF") +
    theme_classic(base_size = 12) +
    theme(
      plot.title = element_text(face = "bold"),
      legend.position = "none"
    )
}

# ------------------------------------------------------------
# 4.3 Summarize PETH within each mouse
# ------------------------------------------------------------

summarize_mouse_peth <- function(df) {
  
  df %>%
    mutate(time_bin = round(nor.time / PETH_BIN_WIDTH) * PETH_BIN_WIDTH) %>%
    group_by(mouse.ID, intensity, protocol, time_bin) %>%
    summarise(
      mean_signal = mean(normalized_dF, na.rm = TRUE),
      sd_signal = sd(normalized_dF, na.rm = TRUE),
      n = sum(!is.na(normalized_dF)),
      sem = ifelse(n > 1, sd_signal / sqrt(n), NA_real_),
      .groups = "drop"
    )
}

# ------------------------------------------------------------
# 4.4 Plot PETH for one stimulation protocol
# ------------------------------------------------------------

plot_protocol <- function(df, protocol, duration, x_limits) {
  
  plot_data <- df %>% filter(protocol == !!protocol)
  
  ggplot(plot_data, aes(x = time_bin, y = mean_signal,
                        color = as.factor(mouse.ID), fill = as.factor(mouse.ID))) +
    annotate("rect", xmin = 0, xmax = duration,
             ymin = -Inf, ymax = Inf, fill = STIM_COLOR, alpha = 0.1) +
    geom_ribbon(aes(ymin = mean_signal - sem, ymax = mean_signal + sem),
                alpha = 0.3, colour = NA, na.rm = TRUE) +
    geom_line(linewidth = 0.8) +
    geom_vline(xintercept = 0, color = "black", linetype = "dotted") +
    scale_color_manual(values = MY_COLORS, name = "Mouse ID") +
    scale_fill_manual(values = MY_COLORS, name = "Mouse ID") +
    coord_cartesian(xlim = x_limits, ylim = c(-0.1, 0.4)) +
    facet_wrap(~ intensity, nrow = 1) +
    labs(x = "Time (s)", y = "Normalized fluorescence (a.u.)") +
    theme_classic(base_size = 12) +
    theme(legend.position = "right")
}

# ============================================================
# 5. REPRESENTATIVE PHOTOMETRY TRACES
# ============================================================

# Original example 1: dStr, MAT-file index 1
example_dstr <- load_example(EXAMPLE_DSTR_INDEX)

a1 <- plot_example(
  example_dstr, "dStr", DSTR_XLIM, DSTR_YLIM, "#810F7C"
)

# Original example 2: vStr, MAT-file index 17
example_vstr <- load_example(EXAMPLE_VSTR_INDEX)

a2 <- plot_example(
  example_vstr, "vStr", VSTR_XLIM, VSTR_YLIM, "#8C96C6"
)

a <- plot_grid(a1, a2, nrow = 1, align = "tb", axis = "tblr")


# ============================================================
# 6. IMPORT PETH FILES
# ============================================================

peth_files <- list.files(
  OUT_DIR, pattern = "_PETH\\.csv$", recursive = TRUE, full.names = TRUE
)

if (length(peth_files) == 0) {
  stop("No PETH CSV files found. Run script 01 first.")
}

PETH <- dplyr::bind_rows(lapply(peth_files, read.csv))

# Compatibility with original script 01 exports
if (!"normalized_dF" %in% names(PETH) && "zscore" %in% names(PETH)) {
  PETH$normalized_dF <- PETH$zscore
}

if (!"intensity" %in% names(PETH) && "intenisty" %in% names(PETH)) {
  PETH$intensity <- PETH$intenisty
}

# Original manual group corrections
PETH$group[PETH$mouse.ID %in% c(796284, 796287)] <- "ctrl"


# ============================================================
# 7. PETH SUMMARIES
# ============================================================

PETH_summary <- summarize_mouse_peth(PETH)

b <- plot_protocol(
  PETH_summary,
  protocol = "1 sec, 3 sec",
  duration = 1,
  x_limits = c(-1, 2)
)

c <- plot_protocol(
  PETH_summary,
  protocol = "5 sec, 10 sec",
  duration = 5,
  x_limits = c(-1, 6)
)

bc <- plot_grid(b, c, nrow = 1, align = "tb", axis = "tblr", rel_widths = c(1, 0.4))


# ============================================================
# 8. COMBINE AND EXPORT FIGURE
# ============================================================

final_plot <- plot_grid(
  a, bc, nrow = 2, align = "lr", axis = "tblr",
  labels = "AUTO", rel_heights = c(1, 2)
)

ggsave(
  file.path(OUT_DIR, "opto+dLight.pdf"),
  final_plot, width = 12, height = 6
)

print(final_plot)
